def comps(g):
    H,W=len(g),len(g[0]); seen=[[False]*W for _ in range(H)]; out=[]
    for i in range(H):
        for j in range(W):
            if g[i][j]==1 and not seen[i][j]:
                q=deque([(i,j)]);seen[i][j]=True;c=[]
                while q:
                    a,b=q.popleft();c.append((a,b))
                    for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                        x,y=a+da,b+db
                        if 0<=x<H and 0<=y<W and g[x][y]==1 and not seen[x][y]:
                            seen[x][y]=True;q.append((x,y))
                out.append(c)
    return out
# Hypothesis: cavity = 0-region not connected to border; every 1-cell adjacent to a cavity cell is recolored
# to the special cell's color of its component (if comp has one).
def f(g, diag=False):
    H,W=len(g),len(g[0])
    # unreachable 0-cells (via 4-dir or 8-dir if diag)
    R=[[False]*W for _ in range(H)]; q=deque()
    for i in range(H):
        for j in (0,W-1):
            if g[i][j]==0 and not R[i][j]: R[i][j]=True;q.append((i,j))
    for j in range(W):
        for i in (0,H-1):
            if g[i][j]==0 and not R[i][j]: R[i][j]=True;q.append((i,j))
    dd=((1,1),(1,-1),(-1,1),(-1,-1)) if diag else None
    while q:
        a,b=q.popleft()
        D=((1,0),(-1,0),(0,1),(0,-1))+dd if dd else ((1,0),(-1,0),(0,1),(0,-1))
        for da,db in D:
            x,y=a+da,b+db
            if 0<=x<H and 0<=y<W and g[x][y]==0 and not R[x][y]:
                R[x][y]=True;q.append((x,y))
    cav=[(i,j) for i in range(H) for j in range(W) if not R[i][j]]
    out=[row[:] for row in g]
    for c in comps(g):
        spec={g[a][b] for a,b in c if g[a][b]!=1}
        sp=list(spec)[0] if spec else None
        if sp is None: continue
        for a,b in c:
            if (a,b) in cav or any(abs(a-i)<=1 and abs(b-j)<=1 for i,j in cav):
                out[a][b]=sp
    return out
